boolean isValid(String s) {
    Deque<Character> stack = new ArrayDeque<>();
    Map<Character,Character> close = Map.of(')','(', ']','[', '}','{');
    for (char c : s.toCharArray()) {
        if (close.containsValue(c)) stack.push(c);        // opener
        else if (close.containsKey(c)) {                  // closer
            if (stack.isEmpty() || stack.pop() != close.get(c)) return false;
        }
    }
    return stack.isEmpty();   // leftover openers => invalid
}

// "([])": push ( , push [ , ] pops [ ok, ) pops ( ok, empty -> true
// "([)]": ) pops [ -> mismatch -> false
