class MyStack {
    Queue<Integer> q1 = new ArrayDeque<>(), q2 = new ArrayDeque<>();
    void push(int x) {
        q2.offer(x);                       // new element first
        while (!q1.isEmpty()) q2.offer(q1.poll());  // move the rest behind it
        Queue<Integer> t = q1; q1 = q2; q2 = t;     // swap
    }
    int pop()  { return q1.poll(); }       // O(1)
    int top()  { return q1.peek(); }       // O(1)
    boolean empty() { return q1.isEmpty(); }
}

// push1 -> q1:[1]; push2 -> q2:[2], move 1 -> [2,1], swap -> q1:[2,1]
// pop -> 2 (newest, LIFO correct)
```

