int[] dailyTemperatures(int[] t) {
    int[] ans = new int[t.length];
    Deque<Integer> stack = new ArrayDeque<>();   // indices, decreasing temps
    for (int i = 0; i < t.length; i++) {
        while (!stack.isEmpty() && t[i] > t[stack.peek()]) {
            int j = stack.pop();        // i is the next warmer day for j
            ans[j] = i - j;             // distance in days
        }
        stack.push(i);
    }
    return ans;                         // leftover indices stay 0
}

// t = {73,74,75,71,69,72,76,73}
// ans = {1,1,4,2,1,1,0,0} - each index pushed/popped once -> O(n)
